%[text] ## Initial 
close
%loadMapdt(2,1) Type this at CW
ldos_conductance_Together__Constants;
iph = 2;% 1 or 2
vFcs = vFcss(iph,:);
lenperpix = abs(map.x(1) - map.x(2));
numPixel41nm = 1/lenperpix;% I want to add a length bar but I don't know the unit


%%
%[text] ## Panneling
msb = 2;nsb=5;
s.Avg = subplot(2,5,[2,3,4]); %[output:38bec072]
s.con(1) = subplot(2,5,1); %[output:38bec072]
s.con(2) = subplot(2,5,6); %[output:38bec072]
s.con(3) = subplot(2,5,7); %[output:38bec072]
s.con(4) = subplot(2,5,8); %[output:38bec072]
s.con(5) = subplot(2,5,9); %[output:38bec072]
s.con(6) = subplot(2,5,10); %[output:38bec072]
s.con(7) = subplot(2,5,5); %[output:38bec072]
f=gcf;
f.Position = [0 0 800 500] %[output:38bec072] %[output:592d09c7]
%%
%[text] ## Average Pannel
V = map.vm*1000;
xrng = (0:xyxyr(5)) +xyxyr(-1 + iph*2);
yrng = (0:xyxyr(5)) +xyxyr(iph*2);
Gfcs = map.Gfinal0T(xrng,yrng,:);
f.CurrentAxes = s.Avg;
gfcs = squeeze(mean(mean(Gfcs)))*10;%multiplication is no mean. just reduce the size of ticks
area(V,gfcs,FaceColor=[0.941 0.188 0.463]) %[control:colorPicker:4cb8]{"position":[23,42]} %[output:0781fc0d]
xlim([-760 760]); %[output:0781fc0d]
ylim([0 1]) %[output:0781fc0d]
s.Avg.Clipping ="off"; %[output:0781fc0d]
xline(vFcs,'w:',LineWidth=2) %[output:0781fc0d]
hold on %[output:0781fc0d]
plot(V,gfcs,'k',LineWidth=2.5) %[output:0781fc0d]
hold off %[output:0781fc0d]
xlabel(labeler('E','meV')) %[output:4b0c8a74] %[output:0781fc0d]
ylabel(labeler('LDOS','a.u')) %[output:1bec3273] %[output:0781fc0d]
center_preserve_resizeAx(s.Avg,[.9 1.2]) %[output:0781fc0d]
s.Avg.Position = s.Avg.Position + [0.02 0 0 0] %[output:53722db5] %[output:0781fc0d]
insert_pindx(s.Avg,"a") %[output:0781fc0d]
% yticks(yticks*10)
%%
%[text] ## E-wise Pannel
isBottoms = [true false false false false false true];
for iE = 1:7
    f.CurrentAxes = s.con(iE);
    [vv, vi] = min(abs(V-vFcs(iE)));
    views(Gfcs(:,:,vi)) %[output:883fedc6]
    climsc([-2 2]).Standard
    SoD.draw(cnrSoDs{iph},sclSoD,thtSoD,1)
    colormap jet
    xticks([]);yticks([])
    center_preserve_resizeAx(s.con(iE),[1.2 1.2])
    resizeAxesToSquare(s.con(iE));
    draw_tri(s.Avg,s.con(iE),[vFcs(iE) 0],isBottoms(iE))
    insert_valtage(s.con(iE),vFcs(iE))
    insert_pindx(s.con(iE),string(char('a'+iE)))
    
end
iEs = [1 7];
for ind = 1:2 %[output:group:52563da3]
    iE = iEs(ind);
    ax = s.con(iE);
    sax = s.con(iE-(-1)^ind);
    cb = colorbar(ax,"south"); %[output:883fedc6]
    cb.Ticks = [];
    xywh = cb.Position;
    y_new = (ax.Position(2)+ sax.Position(2)+sax.Position(4)-xywh(4))/2;
    xywh(2) = y_new;
    cb.Position = xywh;
    for jnd = 1:2
        switch jnd
            case 1
                str = '-2\sigma';
                dir = 'left';
            case 2
                str = '2\sigma';
                dir = 'right';
        end
        annotation("textbox",xywh +[0 xywh(4) 0 0] + [-1 0 2 0]*xywh(3)*.1,...
            String=str,EdgeColor="none",HorizontalAlignment=dir,...
            VerticalAlignment="middle")
    end
end %[output:group:52563da3]
